// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Login
	// (POST /api/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Logout
	// (POST /api/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe Get current auth state
	// (GET /api/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListGlossaries List glossaries
	// (GET /api/glossaries)
	ListGlossaries(w http.ResponseWriter, r *http.Request)
	// CreateGlossary Create glossary
	// (POST /api/glossaries)
	CreateGlossary(w http.ResponseWriter, r *http.Request)
	// DeleteGlossary Delete glossary
	// (DELETE /api/glossaries/{glossaryId})
	DeleteGlossary(w http.ResponseWriter, r *http.Request, glossaryId string)
	// GetGlossary Get glossary
	// (GET /api/glossaries/{glossaryId})
	GetGlossary(w http.ResponseWriter, r *http.Request, glossaryId string)
	// UpdateGlossary Update glossary
	// (PUT /api/glossaries/{glossaryId})
	UpdateGlossary(w http.ResponseWriter, r *http.Request, glossaryId string)
	// ListLanguages Supported source and target languages
	// (GET /api/languages)
	ListLanguages(w http.ResponseWriter, r *http.Request)
	// ListModels Local models (whisper, Gemma) and their download status (AI-13)
	// (GET /api/models)
	ListModels(w http.ResponseWriter, r *http.Request)
	// DownloadModel Start (or resume) a model download; progress is polled via GET /api/models and pushed on /ws/admin
	// (POST /api/models/{modelId}/download)
	DownloadModel(w http.ResponseWriter, r *http.Request, modelId string)
	// GetNetworkInfo LAN addresses and the base URL used for QR codes (OUT-4)
	// (GET /api/network)
	GetNetworkInfo(w http.ResponseWriter, r *http.Request)
	// ListOverlayPresets Public, the overlay page loads its preset without auth
	// (GET /api/overlay-presets)
	ListOverlayPresets(w http.ResponseWriter, r *http.Request)
	// CreateOverlayPreset Create overlay preset
	// (POST /api/overlay-presets)
	CreateOverlayPreset(w http.ResponseWriter, r *http.Request)
	// DeleteOverlayPreset Delete overlay preset
	// (DELETE /api/overlay-presets/{presetId})
	DeleteOverlayPreset(w http.ResponseWriter, r *http.Request, presetId string)
	// GetOverlayPreset Get overlay preset
	// (GET /api/overlay-presets/{presetId})
	GetOverlayPreset(w http.ResponseWriter, r *http.Request, presetId string)
	// UpdateOverlayPreset Update overlay preset
	// (PUT /api/overlay-presets/{presetId})
	UpdateOverlayPreset(w http.ResponseWriter, r *http.Request, presetId string)
	// ListProviders Provider availability and the resolved default (AI-4, AI-11)
	// (GET /api/providers)
	ListProviders(w http.ResponseWriter, r *http.Request)
	// ListPublicSessions Sessions visible to the audience (no tokens, no config)
	// (GET /api/public/sessions)
	ListPublicSessions(w http.ResponseWriter, r *http.Request)
	// GetPublicSession Get public session
	// (GET /api/public/sessions/{sessionId})
	GetPublicSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// ListCaptions Final captions history (JSON, paginated)
	// (GET /api/public/sessions/{sessionId}/captions)
	ListCaptions(w http.ResponseWriter, r *http.Request, sessionId SessionId, params ListCaptionsParams)
	// GetSubtitles Subtitle file (live or export) in VTT, SRT, TXT or JSON (OUT-6, OUT-7, OUT-8)
	// (GET /api/public/sessions/{sessionId}/subtitles)
	GetSubtitles(w http.ResponseWriter, r *http.Request, sessionId SessionId, params GetSubtitlesParams)
	// ListRecordings List recordings
	// (GET /api/recordings)
	ListRecordings(w http.ResponseWriter, r *http.Request, params ListRecordingsParams)
	// GetRecordingUsage Disk usage of recordings (REC-5)
	// (GET /api/recordings/usage)
	GetRecordingUsage(w http.ResponseWriter, r *http.Request)
	// DeleteRecording Delete recording
	// (DELETE /api/recordings/{recordingId})
	DeleteRecording(w http.ResponseWriter, r *http.Request, recordingId RecordingId)
	// GetRecording Get recording
	// (GET /api/recordings/{recordingId})
	GetRecording(w http.ResponseWriter, r *http.Request, recordingId RecordingId)
	// GetRecordingAudio Recorded audio (AAC in fragmented MP4); supports HTTP Range (REC-2)
	// (GET /api/recordings/{recordingId}/audio)
	GetRecordingAudio(w http.ResponseWriter, r *http.Request, recordingId RecordingId, params GetRecordingAudioParams)
	// ReprocessRecording Re-transcribe/translate a recording offline (REC-6, stretch)
	// (POST /api/recordings/{recordingId}/reprocess)
	ReprocessRecording(w http.ResponseWriter, r *http.Request, recordingId RecordingId)
	// ListSecrets Known secrets with masked hints only; values are never returned (SEC-1)
	// (GET /api/secrets)
	ListSecrets(w http.ResponseWriter, r *http.Request)
	// DeleteSecret Delete secret
	// (DELETE /api/secrets/{name})
	DeleteSecret(w http.ResponseWriter, r *http.Request, name SecretName)
	// PutSecret Write-only; stores in OS keychain or encrypted file (SEC-2, SEC-3)
	// (PUT /api/secrets/{name})
	PutSecret(w http.ResponseWriter, r *http.Request, name SecretName)
	// ValidateSecret Check the stored secret against its service (e.g. Gemini API key) (SEC-5)
	// (POST /api/secrets/{name}/validate)
	ValidateSecret(w http.ResponseWriter, r *http.Request, name SecretName)
	// ListSessions List sessions (admin view)
	// (GET /api/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// CreateSession Create session
	// (POST /api/sessions)
	CreateSession(w http.ResponseWriter, r *http.Request)
	// DeleteSession Delete session
	// (DELETE /api/sessions/{sessionId})
	DeleteSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// GetSession Get session
	// (GET /api/sessions/{sessionId})
	GetSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// UpdateSession Update session
	// (PATCH /api/sessions/{sessionId})
	UpdateSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// PatchCaption Live correction, edit or hide a caption line (ADM-4)
	// (PATCH /api/sessions/{sessionId}/captions/{segmentId})
	PatchCaption(w http.ResponseWriter, r *http.Request, sessionId SessionId, segmentId string, params PatchCaptionParams)
	// RotateIngestToken Rotate the per-session ingest token (invalidates the previous one)
	// (POST /api/sessions/{sessionId}/ingest-token)
	RotateIngestToken(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// PauseSession Pause session
	// (POST /api/sessions/{sessionId}/pause)
	PauseSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// StopFileSource Stop file source
	// (DELETE /api/sessions/{sessionId}/sources/file)
	StopFileSource(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// StartFileSource Feed a local file or URL at real-time speed as the session's audio (AUD-3, dev/test)
	// (POST /api/sessions/{sessionId}/sources/file)
	StartFileSource(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// StartSession Start session
	// (POST /api/sessions/{sessionId}/start)
	StartSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// GetSessionStatus Live status snapshot (the dashboard also receives it via /ws/admin)
	// (GET /api/sessions/{sessionId}/status)
	GetSessionStatus(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// StopSession Stop session
	// (POST /api/sessions/{sessionId}/stop)
	StopSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// SendTestStreamCaption Send a test caption to the configured stream-caption target (CC-3)
	// (POST /api/sessions/{sessionId}/stream-captions/test)
	SendTestStreamCaption(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// DeleteYoutubeCaptionUrl Remove the YouTube caption ingestion URL
	// (DELETE /api/sessions/{sessionId}/stream-captions/youtube-url)
	DeleteYoutubeCaptionUrl(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// PutYoutubeCaptionUrl Set the YouTube caption ingestion URL (write-only secret) (CC-1, CC-2)
	// (PUT /api/sessions/{sessionId}/stream-captions/youtube-url)
	PutYoutubeCaptionUrl(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// GetSettings Get settings
	// (GET /api/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Update settings
	// (PUT /api/settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// GetSetupStatus First-run setup status
	// (GET /api/setup)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// CompleteSetup Set the admin PIN on first run (only allowed while no PIN exists)
	// (POST /api/setup)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// RunBenchmark Run the local provider on a bundled clip and report real-time factor (AI-12)
	// (POST /api/system/benchmark)
	RunBenchmark(w http.ResponseWriter, r *http.Request)
	// GetHardwareReport Hardware self-check and recommended local model sizes (AI-12)
	// (GET /api/system/hardware)
	GetHardwareReport(w http.ResponseWriter, r *http.Request)
	// GetSystemInfo Version, build and feature flags (e.g. SRT availability)
	// (GET /api/system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// GetTlsInfo Get TLS info
	// (GET /api/tls)
	GetTlsInfo(w http.ResponseWriter, r *http.Request)
	// DownloadCaCert Local CA certificate to install on LAN devices (TLS-4)
	// (GET /api/tls/ca.crt)
	DownloadCaCert(w http.ResponseWriter, r *http.Request)
	// GetHealth Liveness/readiness probe
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// WsAdmin Admin event stream (session status, levels, latency, errors) (ADM-1)
	// (GET /ws/admin)
	WsAdmin(w http.ResponseWriter, r *http.Request)
	// WsCaptions Live caption stream for one session (OUT-1)
	// (GET /ws/captions/{sessionId})
	WsCaptions(w http.ResponseWriter, r *http.Request, sessionId SessionId, params WsCaptionsParams)
	// WsIngest Audio ingest WebSocket (AUD-1)
	// (GET /ws/ingest/{sessionId})
	WsIngest(w http.ResponseWriter, r *http.Request, sessionId SessionId)
}

